package com.fileproc.service

import java.io.File
import java.nio.file.Files
import java.nio.file.Path
import java.nio.file.Paths
import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap

data class FeatureFlags(
    val enableCaching: Boolean = true,
    val enableTemplateExpansion: Boolean = true,
    val enableAuditLog: Boolean = true,
    val maxFileSizeKb: Int = 512,
    val allowedExtensions: Set<String> = setOf("html", "txt", "xml", "shtml"),
    val sandboxMode: Boolean = true
)

data class ProcessingContext(
    val requestId: String,
    val userId: String,
    val basePath: Path,
    val flags: FeatureFlags
)

object DirectiveRegistry {
    private val safeDirectives = setOf("echo", "printenv", "set", "if", "elif", "else", "endif")
    private val dangerousDirectives = setOf("exec", "include", "fsize", "flastmod")

    fun isSafe(directive: String): Boolean = directive.trim().lowercase() in safeDirectives
    fun isDangerous(directive: String): Boolean = directive.trim().lowercase() in dangerousDirectives
    fun isKnown(directive: String): Boolean = isSafe(directive) || isDangerous(directive)
}

class ContentSanitizer(private val flags: FeatureFlags) {
    private val ssiPattern = Regex("""<!--#(\w+)\s+([^>]*?)-->""")

    fun sanitize(content: String, context: ProcessingContext): String {
        if (!flags.sandboxMode) {
            return content
        }
        return processDirectives(content, context)
    }

    private fun processDirectives(content: String, context: ProcessingContext): String {
        val matches = ssiPattern.findAll(content)
        var result = content

        for (match in matches) {
            val directive = match.groupValues[1]
            val params = match.groupValues[2]

            if (DirectiveRegistry.isDangerous(directive)) {
                result = result.replace(match.value, "<!-- directive removed: $directive -->")
                logAudit(context, "Removed dangerous directive: $directive")
            }
        }
        return result
    }

    private fun logAudit(context: ProcessingContext, message: String) {
        if (flags.enableAuditLog) {
            println("[AUDIT][${context.requestId}][${context.userId}] $message")
        }
    }
}

class TemplateEngine(private val flags: FeatureFlags) {
    private val variablePattern = Regex("""\$\{([\w.]+)\}""")
    private val includeVirtualPattern = Regex("""<!--#include\s+virtual="([^"]+)"\s*-->""")

    fun expand(content: String, context: ProcessingContext, variables: Map<String, String>): String {
        if (!flags.enableTemplateExpansion) {
            return content
        }
        var expanded = expandVariables(content, variables)
        expanded = resolveVirtualIncludes(expanded, context)
        return expanded
    }

    private fun expandVariables(content: String, variables: Map<String, String>): String {
        return variablePattern.replace(content) { match ->
            val varName = match.groupValues[1]
            variables.getOrDefault(varName, match.value)
        }
    }

    private fun resolveVirtualIncludes(content: String, context: ProcessingContext): String {
        return includeVirtualPattern.replace(content) { match ->
            val virtualPath = match.groupValues[1]
            loadVirtualResource(virtualPath, context)
        }
    }

    private fun loadVirtualResource(virtualPath: String, context: ProcessingContext): String {
        val resolved = context.basePath.resolve(virtualPath).normalize()
        if (!resolved.startsWith(context.basePath)) {
            return "<!-- access denied -->"
        }
        return try {
            Files.readString(resolved)
        } catch (e: Exception) {
            "<!-- resource not found -->"
        }
    }
}

class FileProcessingService(
    private val flags: FeatureFlags = FeatureFlags()
) {
    private val cache = ConcurrentHashMap<String, String>()
    private val sanitizer = ContentSanitizer(flags)
    private val templateEngine = TemplateEngine(flags)

    fun processFile(filePath: String, context: ProcessingContext, variables: Map<String, String> = emptyMap()): String {
        val cacheKey = computeCacheKey(filePath, context)

        if (flags.enableCaching) {
            cache[cacheKey]?.let { return it }
        }

        val path = context.basePath.resolve(filePath).normalize()
        validatePath(path, context)
        validateExtension(path)
        validateSize(path)

        var content = Files.readString(path)

        // Pipeline: sanitize first, then expand templates
        content = sanitizer.sanitize(content, context)
        content = templateEngine.expand(content, context, variables)

        if (flags.enableCaching) {
            cache[cacheKey] = content
        }
        return content
    }

    private fun validatePath(path: Path, context: ProcessingContext) {
        if (!path.startsWith(context.basePath)) {
            throw SecurityException("Path traversal detected: $path")
        }
    }

    private fun validateExtension(path: Path) {
        val ext = path.toString().substringAfterLast('.', "")
        if (ext !in flags.allowedExtensions) {
            throw SecurityException("Disallowed extension: $ext")
        }
    }

    private fun validateSize(path: Path) {
        val sizeKb = Files.size(path) / 1024
        if (sizeKb > flags.maxFileSizeKb) {
            throw SecurityException("File too large: ${sizeKb}KB > ${flags.maxFileSizeKb}KB")
        }
    }

    private fun computeCacheKey(filePath: String, context: ProcessingContext): String {
        val digest = MessageDigest.getInstance("SHA-256")
        val input = "${context.userId}:$filePath:${context.flags.sandboxMode}"
        return digest.digest(input.toByteArray()).joinToString("") { "%02x".format(it) }
    }

    fun clearCache() {
        cache.clear()
    }
}

fun main() {
    val flags = FeatureFlags(
        enableCaching = true,
        enableTemplateExpansion = true,
        sandboxMode = true
    )
    val basePath = Paths.get("/var/www/content")
    val context = ProcessingContext(
        requestId = "req-001",
        userId = "user-42",
        basePath = basePath,
        flags = flags
    )
    val service = FileProcessingService(flags)
    val result = service.processFile("index.shtml", context, mapOf("site.name" to "MyApp"))
    println(result)
}
